export function getStaticEmojiCategories() {
  return staticEmojiCategories;
}

export function getAllStaticEmojis() {
  const all = [];
  for (const cat of staticEmojiCategories) {
    for (const emoji of cat.emojis) {
      all.push({
        ...emoji,
        category: cat.name,
        isStatic: true
      });
    }
  }
  return all;
}